SELECT channel_id, block_key, pg_catalog.count(*)::bigint AS block_records
FROM @{blocks/composite_person}
GROUP BY channel_id, block_key

SELECT channel_id, block_key, block_records, 2::bigint AS max_block_records
FROM @{block-stats/composite_person}
WHERE block_records > 2

SELECT source_record_id, field_name, 'exact_email'::text AS channel_id, canonical_bytes AS block_key, source_sort_key
FROM @{normalized/email}
WHERE field_name = 'email' AND state = 'value' AND canonical_bytes IS NOT NULL

SELECT channel_id, block_key, pg_catalog.count(*)::bigint AS block_records
FROM @{blocks/exact_email}
GROUP BY channel_id, block_key

SELECT channel_id, block_key, block_records, 2::bigint AS max_block_records
FROM @{block-stats/exact_email}
WHERE block_records > 2

SELECT source_record_id, field_name, 'prefix_name'::text AS channel_id, pg_catalog.left(normalized, 3) AS block_key, source_sort_key
FROM @{normalized/name}
WHERE field_name = 'name' AND state = 'value' AND normalized IS NOT NULL

SELECT channel_id, block_key, pg_catalog.count(*)::bigint AS block_records
FROM @{blocks/prefix_name}
GROUP BY channel_id, block_key

SELECT channel_id, block_key, block_records, 2::bigint AS max_block_records
FROM @{block-stats/prefix_name}
WHERE block_records > 2

SELECT channel_id, block_key, pg_catalog.count(*)::bigint AS block_records
FROM @{blocks/token_name}
GROUP BY channel_id, block_key

SELECT channel_id, block_key, block_records, 2::bigint AS max_block_records
FROM @{block-stats/token_name}
WHERE block_records > 2

SELECT candidate_pairs, 10::bigint AS max_candidate_pairs
FROM @{pair-stats/person}
WHERE candidate_pairs > 10
